import pandas as pd
import numpy as np
from sklearn.cluster import KMeans
from sklearn.preprocessing import StandardScaler

features = ['energy', 'danceability', 'valence', 'tempo']

# Top 10 by popularity with selected columns
top10_df = df.nlargest(10, 'popularity')[['track_name', 'artists', 'popularity'] + features].reset_index(drop=True)

# Summary statistics for top-10 subset
top10_stats = top10_df[features].agg(['mean', 'median', 'std', 'min', 'max']).to_dict()

# Correlations between popularity and each feature across whole dataset
corrs = df[['popularity'] + features].corr().loc['popularity', features].to_dict()

# Top 10% most popular threshold and group stats
cutoff = df['popularity'].quantile(0.9)
top10pct_df = df[df['popularity'] >= cutoff]
rest_df = df[df['popularity'] < cutoff]

def group_feature_stats(group_df):
    agg = group_df[features].agg(['mean', 'median', 'std']).to_dict()
    return agg

top10pct_stats = group_feature_stats(top10pct_df)
rest_stats = group_feature_stats(rest_df)

# K-means clustering on standardized features for k=2..4
X = df[features].copy()
valid_idx = X.dropna().index
X_valid = X.loc[valid_idx].values
scaler = StandardScaler()
X_scaled = scaler.fit_transform(X_valid)

kmeans_results = {}
for k in [2, 3, 4]:
    km = KMeans(n_clusters=k, random_state=42, n_init=10)
    labels = km.fit_predict(X_scaled)
    centers_std = km.cluster_centers_
    centers_orig = scaler.inverse_transform(centers_std)
    # For each cluster compute size and proportion of high-popularity tracks
    labels_series = pd.Series(labels, index=valid_idx)
    cluster_info = {}
    for i in range(k):
        cluster_idx = labels_series[labels_series == i].index
        size = int(len(cluster_idx))
        if size == 0:
            prop_high = 0.0
        else:
            prop_high = float((df.loc[cluster_idx, 'popularity'] >= cutoff).sum()) / size
        center_dict = {features[j]: float(centers_orig[i, j]) for j in range(len(features))}
        cluster_info[i] = {
            'size': size,
            'proportion_high_popularity': prop_high,
            'center': center_dict
        }
    kmeans_results[k] = cluster_info

# Helper to convert numpy/pandas types to JSON-safe Python types
def to_py(obj):
    if isinstance(obj, dict):
        return {str(k): to_py(v) for k, v in obj.items()}
    if isinstance(obj, (list, tuple)):
        return [to_py(v) for v in obj]
    if isinstance(obj, pd.DataFrame):
        return to_py(obj.to_dict(orient='records'))
    if isinstance(obj, pd.Series):
        return to_py(obj.to_dict())
    if isinstance(obj, np.ndarray):
        return to_py(obj.tolist())
    if pd.isna(obj):
        return None
    if isinstance(obj, (np.integer,)):
        return int(obj)
    if isinstance(obj, (np.floating,)):
        v = float(obj)
        if np.isnan(v):
            return None
        return v
    return obj

data = to_py({
    'top_10': top10_df.to_dict(orient='records'),
    'top_10_summary': top10_stats,
    'correlations_with_popularity': corrs,
    'top_10pct_vs_rest': {
        'cutoff_popularity': float(cutoff),
        'top_10_percent_stats': top10pct_stats,
        'rest_stats': rest_stats
    },
    'kmeans_clustering': kmeans_results
})
